local config = {
  ui_story_5041_50410101_1_dialog_content = "Luke, there's a package for you!",
  ui_story_5041_50410101_2_dialog_content = "PlayerName? Why is it you delivering?",
  ui_story_5041_50410101_3_dialog_content = "And who is this?",
  ui_story_5041_50410101_4_dialog_content = "This is Lady Jeriah from the Courier Union. I'm just helping out for Mooncrown Day.",
  ui_story_5041_50410101_5_dialog_content = "Hello, Deputy Commander of the White Flame Mercenaries. Your reputation precedes you.",
  ui_story_5041_50410101_6_dialog_content = "A senior member of the Courier Union? An honor to meet you. But who would send me a package?",
  ui_story_5041_50410101_7_dialog_content = "Why don't you open it? Should we give you some privacy?",
  ui_story_5041_50410101_8_dialog_content = "No need. If it turns out to be a threat from a nemesis, I'll be needing more info from you.",
  ui_story_5041_50410101_9_dialog_content = "Aren't you a bit too cautious? Such gentle packaging couldn't possibly be from a rival.",
  ui_story_5041_50410101_10_dialog_content = "Hmm, there's a note attached inside the box.",
  ui_story_5041_50410101_11_dialog_content = "\"Commander Luke, sorry to communicate with you this way, but the mission comes first, so we must rely on correspondence.\"",
  ui_story_5041_50410101_12_dialog_content = "\"We have all witnessed firsthand your sense of duty to the White Flame Mercenaries and consideration for everybody.\"",
  ui_story_5041_50410101_13_dialog_content = "\"All we do is carry out the missions, but you must think about the organization's future and how to expand it...\"",
  ui_story_5041_50410101_14_dialog_content = "\"You also care for every member's well-being down to the minute details. We often joke around and say you're omnipotent.\"",
  ui_story_5041_50410101_15_dialog_content = "\"However, I know you're a normal person as well, and burdening so much for so long makes you weary at times.\"",
  ui_story_5041_50410101_16_dialog_content = "It's from them... I told them not to call me \"commander.\" Can't believe they made time to write this in the middle of a mission.",
  ui_story_5041_50410101_17_dialog_content = "That's very touching. I guess your mercenaries care a lot about you.",
  ui_story_5041_50410101_18_dialog_content = "That's because Luke is a very responsible person, a fact obvious to everyone.",
  ui_story_5041_50410101_19_dialog_content = "What else does the letter say?",
  ui_story_5041_50410101_20_dialog_content = "\"You get up early and go to bed late every night, so we took the time to make you an herbal pouch.\"",
  ui_story_5041_50410101_21_dialog_content = "\"We heard these herbs can aid sleep. Please try it out the next time you sleep by putting it next to your pillow.\"",
  ui_story_5041_50410101_22_dialog_content = "\"We hope you can sneak in a nap every now and then too.\"",
  ui_story_5041_50410101_23_dialog_content = "\"From, Your Mercenaries.\"",
  ui_story_5041_50410101_24_dialog_content = "Doing all this on a mission... I was only doing what I was supposed to do, really.",
  ui_story_5041_50410101_25_dialog_content = "I certainly didn't expect this.",
  ui_story_5041_50410101_26_dialog_content = "Yeah, Luke, you should take it easy once in a while. You're prone to mistakes if you're always taut as a wire.",
  ui_story_5041_50410101_27_dialog_content = "Proper rest is essential to completing every new task that comes our way... I think they're right.",
  ui_story_5041_50410101_28_dialog_content = "Since everyone seems to be saying the same thing, I shall take the advice.",
  ui_story_5041_50410101_29_dialog_content = "Once I'm done today, I'll take a nap with the pouch next to my pillow.",
  ui_story_5041_50410201_1_dialog_content = "Huff, huff... There you are, Commander Hiiro!",
  ui_story_5041_50410201_2_dialog_content = "PlayerName?",
  ui_story_5041_50410201_3_dialog_content = "What are you doing here? Did something happen in Illumina?!",
  ui_story_5041_50410201_4_dialog_content = "No, I'm just delivering mail with Jeriah from the Courier Union. Here, a package for you, a pretty hefty one too.",
  ui_story_5041_50410201_5_dialog_content = "Heh, I think the sender is an interesting one.",
  ui_story_5041_50410201_6_dialog_content = "Weird, who would send a package to me all the way here on the front line?",
  ui_story_5041_50410201_7_dialog_content = "That's normal. It's Mooncrown Day, after all.",
  ui_story_5041_50410201_8_dialog_content = "Mooncrown Day? Ah, right... I completely forgot.",
  ui_story_5041_50410201_9_dialog_content = "I'm pressed for time, so let's see what's inside... Wait, let me see who sent it first.",
  ui_story_5041_50410201_10_dialog_content = "Oh, it's from Zoya. These are...",
  ui_story_5041_50410201_11_dialog_content = "Sawdust buns, canned meat, cream of mushroom soup, chocolate beans, and even cinnamon rolls.",
  ui_story_5041_50410201_12_dialog_content = "They're all Illumina specialties.",
  ui_story_5041_50410201_13_dialog_content = "I believe it's a tradition for lovers in Illumina to gift hand-made cinnamon rolls. Very romantic.",
  ui_story_5041_50410201_14_dialog_content = "It was probably unintentional on Zoya's part.",
  ui_story_5041_50410201_15_dialog_content = "(Somehow, I don't think it was unintentional.)",
  ui_story_5041_50410201_16_dialog_content = "I think there's writing on the box.",
  ui_story_5041_50410201_17_dialog_content = "\"Lady Hiiro, thank you for your work on the front line! I heard you'd be away for long this time. I can only imagine how exhausting that will be.\"",
  ui_story_5041_50410201_18_dialog_content = "\"I imagine you'll be craving Illumina delicacies, so I asked Gram to put together a care package.\"",
  ui_story_5041_50410201_19_dialog_content = "\"But I did make the cinnamon rolls myself, however, so make sure you taste that first!\"",
  ui_story_5041_50410201_20_dialog_content = "(I can picture the look on Zoya's face.)",
  ui_story_5041_50410201_21_dialog_content = "\"Lady Hiiro, I would love to spend Mooncrown Day with you, but the front line is the priority, so please take care of yourself!\"",
  ui_story_5041_50410201_22_dialog_content = "\"My heart and soul belong to you, my beautiful, strong, and cool Lady Hiiro!\"",
  ui_story_5041_50410201_23_dialog_content = "A person who can read a sentence like that out loud with a straight face is truly extraordinary.",
  ui_story_5041_50410201_24_dialog_content = "Ahaha, I agree.",
  ui_story_5041_50410201_25_dialog_content = "I do appreciate Zoya's thoughts, and I certainly miss Illumina food.",
  ui_story_5041_50410201_26_dialog_content = "She's always so caring. I'm sure everyone in the research lab likes her as well.",
  ui_story_5041_50410201_27_dialog_content = "I think she only cares about you...",
  ui_story_5041_50410201_28_dialog_content = "Since she made the cinnamon rolls herself, I shall take a bite.",
  ui_story_5041_50410201_29_dialog_content = "*chews*",
  ui_story_5041_50410201_30_dialog_content = "Mm. I truly can taste Zoya's feelings from this.",
  ui_story_5041_50410201_31_dialog_content = "(I'm gonna warrant a guess it tastes very questionable...)",
  ui_story_5041_50410201_32_dialog_content = "Thank you for delivering this to the front line. Why don't you two stay the night? We can feast on this food together.",
  ui_story_5041_50410201_33_dialog_content = "Sure, I'm quite interested in Illumina fare.",
  ui_story_5041_50410201_34_dialog_content = "Hey, we still have more mail to deliver!",
  ui_story_5041_50410301_1_dialog_content = "Novio, I've got a package for you!",
  ui_story_5041_50410301_2_dialog_content = "We went to the Winter Palace first, but surprisingly, you weren't there.",
  ui_story_5041_50410301_3_dialog_content = "I'm just out here taking a walk. I didn't expect you to be the courier, PlayerName.",
  ui_story_5041_50410301_4_dialog_content = "I came with Jeriah, so I'm really just assisting.",
  ui_story_5041_50410301_5_dialog_content = "The scenery in Northland is always spectacular, no matter how many times I've been here.",
  ui_story_5041_50410301_6_dialog_content = "It's secluded from the rest of the continent, almost in its own world. I hope you like it here.",
  ui_story_5041_50410301_7_dialog_content = "Oh yeah, here's your package. It's from Lola!",
  ui_story_5041_50410301_8_dialog_content = "Lola? If I recall correctly, she hasn't been in Northland as of late.",
  ui_story_5041_50410301_9_dialog_content = "She seems to have visited many places. Her cheeks were all red from excitement.",
  ui_story_5041_50410301_10_dialog_content = "Given her personality, she probably had a great time enjoying local snacks and knickknacks.",
  ui_story_5041_50410301_11_dialog_content = "Anyhow, let me take a look inside...",
  ui_story_5041_50410301_12_dialog_content = "Chocolate shaped like Eclipsites?",
  ui_story_5041_50410301_13_dialog_content = "That looks pretty... authentic.",
  ui_story_5041_50410301_14_dialog_content = "There's a note as well.",
  ui_story_5041_50410301_15_dialog_content = "\"Novio, check out this Eclipsite-flavored chocolate I found in an Umbraton candy store. You must try it!\"",
  ui_story_5041_50410301_16_dialog_content = "I have a hard time imagining how Eclipsites would taste.",
  ui_story_5041_50410301_17_dialog_content = "Well, there's always a first for everything.",
  ui_story_5041_50410301_18_dialog_content = "And what's in this black box... Whoa!",
  ui_story_5041_50410301_19_dialog_content = "A-Are you okay, Novio?",
  ui_story_5041_50410301_20_dialog_content = "Is this one of those jack-in-the-box toys? That freaked me out.",
  ui_story_5041_50410301_21_dialog_content = "This head is a little reminiscent of a certain someone...",
  ui_story_5041_50410301_22_dialog_content = "Is it just me, or does it look like Sinsa?",
  ui_story_5041_50410301_23_dialog_content = "It's a fun design, but I should stow it away.",
  ui_story_5041_50410301_24_dialog_content = "\"Ran into an auction in a desert market and couldn't believe no one bid on this cool toy, so I bought it!\"",
  ui_story_5041_50410301_25_dialog_content = "\"I think it's modeled after someone, but no idea who.\"",
  ui_story_5041_50410301_26_dialog_content = "I didn't even know those markets sold these things. How unique.",
  ui_story_5041_50410301_27_dialog_content = "It does fit Lola's style, all right.",
  ui_story_5041_50410301_28_dialog_content = "Let's hope there are no more surprises in this box... Are these dried flowers?",
  ui_story_5041_50410301_29_dialog_content = "They're so pretty...",
  ui_story_5041_50410301_30_dialog_content = "\"I collected these during my travel. They include my favorite wild roses, and some others I don't recognize.\"",
  ui_story_5041_50410301_31_dialog_content = "\"I pressed them into bookmarks. You like to read so I think you'll find them useful!\"",
  ui_story_5041_50410301_32_dialog_content = "\"If you found out what flowers they are, let me know!\"",
  ui_story_5041_50410301_33_dialog_content = "She's such a free spirit... And all the flowers are stunning.",
  ui_story_5041_50410301_34_dialog_content = "I believe these are amaranth, palm lily, and jasmine. I guess I'll have to write back and tell her.",
  ui_story_5041_50410301_35_dialog_content = "Thank you both so much for delivering the package. Would you like to try the chocolate with me?",
  ui_story_5041_50410301_36_dialog_content = "(Eclipsite-flavored chocolate? I think I'll pass.)",
  ui_story_5041_50410301_37_dialog_content = "Thanks a lot.",
  ui_story_5041_50410301_38_dialog_content = "Hey, don't just eat anything!",
  ui_story_5041_50410401_1_dialog_content = "This should be the address... probably?",
  ui_story_5041_50410401_2_dialog_content = "The writing is so illegible, it almost hurts my eyes to read!",
  ui_story_5041_50410401_3_dialog_content = "I can just barely tell it's addressed to Harbor City, but the rest is a jumbled mess...",
  ui_story_5041_50410401_4_dialog_content = "Are we even at the right place?",
  ui_story_5041_50410401_5_dialog_content = "Yes, this is the right place.",
  ui_story_5041_50410401_6_dialog_content = "How are you so sure, Jeriah?",
  ui_story_5041_50410401_7_dialog_content = "Look over there, doesn't that person look like they're waiting for mail?",
  ui_story_5041_50410401_8_dialog_content = "Sigh, will it be here today? I'm kinda tired...",
  ui_story_5041_50410401_9_dialog_content = "When in the world did she get there?! I didn't see her there earlier!",
  ui_story_5041_50410401_10_dialog_content = "Are you talking about me?",
  ui_story_5041_50410401_11_dialog_content = "I've been here all along, but haven't moved since I'm too tired.",
  ui_story_5041_50410401_12_dialog_content = "No wonder I didn't see you...",
  ui_story_5041_50410401_13_dialog_content = "Are you the couriers?",
  ui_story_5041_50410401_14_dialog_content = "Yes, we are, young lady.",
  ui_story_5041_50410401_15_dialog_content = "This is addressed to Ni... Nina?",
  ui_story_5041_50410401_16_dialog_content = "It's Tina. Tee, na.",
  ui_story_5041_50410401_17_dialog_content = "Don't tell me you forgot my name?",
  ui_story_5041_50410401_18_option_content = "I know you!",
  ui_story_5041_50410401_19_dialog_content = "You were the one looking to get stamps from Jeriah in Lumopolis, right?",
  ui_story_5041_50410401_20_dialog_content = "You do remember me.",
  ui_story_5041_50410401_21_dialog_content = "Of course, I have a mind like a steel trap.",
  ui_story_5041_50410401_22_option_content = "I'm not sure...",
  ui_story_5041_50410401_23_dialog_content = "Then let me introduce myself.",
  ui_story_5041_50410401_24_dialog_content = "I'm Judge Tina with the Hall of Justice in Lumopolis. I'm in Harbor City now on official business.",
  ui_story_5041_50410401_25_dialog_content = "May I ask if this is for me?",
  ui_story_5041_50410401_26_dialog_content = "It does look like it says the recipient's name is Tina.",
  ui_story_5041_50410401_27_dialog_content = "Sorry, the writing is just too difficult to make out.",
  ui_story_5041_50410401_28_dialog_content = "I didn't expect to see someone from the Lumo Hall of Justice in Harbor City.",
  ui_story_5041_50410401_29_dialog_content = "It was a long trip, but sleeping in an airship was quite an experience.",
  ui_story_5041_50410401_30_dialog_content = "The ship rocked gently to the wind, and the soft bed was like a cradle.",
  ui_story_5041_50410401_31_dialog_content = "I know that feeling! It's like when I go to bed on the Colossus while its in the air.",
  ui_story_5041_50410401_32_dialog_content = "You have good taste.",
  ui_story_5041_50410401_33_dialog_content = "Judging from your outfit, you must be the one they called Navigator of the Colossus? The Last Caelestite?",
  ui_story_5041_50410401_34_dialog_content = "Er... my titles seem to keep getting fancier...",
  ui_story_5041_50410401_35_dialog_content = "Why don't I just introduce myself?",
  ui_story_5041_50410401_36_dialog_content = "I'm indeed a Caelestite, but just a normal Caelestite.",
  ui_story_5041_50410401_37_dialog_content = "Just call me PlayerName!",
  ui_story_5041_50410401_38_dialog_content = "PlayerName? Hmm, that is an interesting name.",
  ui_story_5041_50410401_39_dialog_content = "I'm helping the Courier Union deliver mail right now. With me here is Jeriah.",
  ui_story_5041_50410401_40_dialog_content = "Hello!",
  ui_story_5041_50410401_41_dialog_content = "What an adorable young lady you are.",
  ui_story_5041_50410401_42_dialog_content = "Anyway, please sign here!",
  ui_story_5041_50410401_43_dialog_content = "Hmm, could this be \"that\"...?",
  ui_story_5041_50410401_44_dialog_content = "<color=#e8d9bb>*sign*</color>",
  ui_story_5041_50410401_45_dialog_content = "\"That\"?",
  ui_story_5041_50410401_46_dialog_content = "Something I've been waiting for all this time, ever since I wrote to that fellow.",
  ui_story_5041_50410401_47_dialog_content = "Well, let me find out for sure...",
  ui_story_5041_50410401_48_dialog_content = "<color=#e8d9bb>Rip—</color>",
  ui_story_5041_50410401_49_dialog_content = "Huh?",
  ui_story_5041_50410401_50_dialog_content = "Hmm...",
  ui_story_5041_50410401_51_dialog_content = "A bag of leaves? And two wild fruits that may or may not be edible...",
  ui_story_5041_50410401_52_dialog_content = "T-The leaves are rotten... They weren't damaged in transit, were they?",
  ui_story_5041_50410401_53_dialog_content = "PlayerName, did you check the condition of the package when you received it?",
  ui_story_5041_50410401_54_dialog_content = "Nope...",
  ui_story_5041_50410401_55_dialog_content = "I saw this package at my door when I left this morning.",
  ui_story_5041_50410401_56_dialog_content = "When I looked and saw that it wasn't for me, I treated it like a package awaiting delivery and brought it with me.",
  ui_story_5041_50410401_57_dialog_content = "That's not how it works, Caelestite.",
  ui_story_5041_50410401_58_dialog_content = "You must check the condition of the contents when you get a package so you know what kind of precautions are necessary for delivering it.",
  ui_story_5041_50410401_59_dialog_content = "It's a basic part of being a courier.",
  ui_story_5041_50410401_60_dialog_content = "Sorry...",
  ui_story_5041_50410401_61_dialog_content = "Uh, what are you talking about?",
  ui_story_5041_50410401_62_dialog_content = "These leaves aren't damaged.",
  ui_story_5041_50410401_63_dialog_content = "They aren't?",
  ui_story_5041_50410401_64_dialog_content = "See this on the leaf? Doesn't it resemble Universese?",
  ui_story_5041_50410401_65_dialog_content = "Yeah, now that you mention it!",
  ui_story_5041_50410401_66_dialog_content = "But it's so crooked, I almost didn't recognize it.",
  ui_story_5041_50410401_67_dialog_content = "I think it reads, \"Thanks\"?",
  ui_story_5041_50410401_68_dialog_content = "These aren't ordinary leaves. They're letter paper.",
  ui_story_5041_50410401_69_dialog_content = "While I'm elated to get this, it's quite unfortunate.",
  ui_story_5041_50410401_70_dialog_content = "The leaves are in random order and the writing is impossible to decipher...",
  ui_story_5041_50410401_71_dialog_content = "Even I can't decipher everything on them...",
  ui_story_5041_50410401_72_dialog_content = "It's so sad that I won't get to know what the little fella wanted to say.",
  ui_story_5041_50410401_73_dialog_content = "But it feels good to get a reply, anyway.",
  ui_story_5041_50410401_74_dialog_content = "Thank you both for delivering it.",
  ui_story_5041_50410401_75_dialog_content = "Who's the little fellow you keep talking about?",
  ui_story_5041_50410401_76_dialog_content = "It sounds like a little brother or sister.",
  ui_story_5041_50410401_77_dialog_content = "Yeah, you could call them that.",
  ui_story_5041_50410401_78_dialog_content = "That fellow is as cute as a kitten and makes you want to cuddle it.",
  ui_story_5041_50410401_79_dialog_content = "Is it a small animal?",
  ui_story_5041_50410401_80_dialog_content = "It's a secret.",
  ui_story_5041_50410401_81_dialog_content = "All right, I won't pry. You're entitled to your privacy, after all.",
  ui_story_5041_50410401_82_dialog_content = "Thank you for choosing the Courier Union. Looking forward to serve you next time!",
  ui_story_5041_50410401_83_dialog_content = "Make sure to confirm the condition of any package you deliver too.",
  ui_story_5041_50410401_84_dialog_content = "Yes...",
  ui_story_5041_50410501_1_dialog_content = "Here you are, Eve!",
  ui_story_5041_50410501_2_dialog_content = "It's you, PlayerName! And who... is this?",
  ui_story_5041_50410501_3_dialog_content = "Hello, young lady, I'm Jeriah from the Courier Union.",
  ui_story_5041_50410501_4_dialog_content = "Oh, a courier. I've never seen anyone from the Union before.",
  ui_story_5041_50410501_5_dialog_content = "Hello, I'm Eve!",
  ui_story_5041_50410501_6_dialog_content = "You've got mail, Eve!",
  ui_story_5041_50410501_7_dialog_content = "It's from Sinsa.",
  ui_story_5041_50410501_8_dialog_content = "My brother? I wonder what he sent me.",
  ui_story_5041_50410501_9_dialog_content = "Probably something very important.",
  ui_story_5041_50410501_10_dialog_content = "This is what he said when he handed us the package...",
  ui_story_5041_50410501_11_dialog_content = "This is an urgent delivery for Eve. Make sure she gets it! Got it?",
  ui_story_5041_50410501_12_dialog_content = "G-Got it!",
  ui_story_5041_50410501_13_dialog_content = "It's her first time being away from home by herself. I must ensure her safety and keep her away from bad guys.",
  ui_story_5041_50410501_14_dialog_content = "I'd be right by her side right now, protecting her from all danger if she hadn't refused to let me tag along.",
  ui_story_5041_50410501_15_dialog_content = "Eve went somewhere? Where did she go?",
  ui_story_5041_50410501_16_dialog_content = "A base located several hundred meters away.",
  ui_story_5041_50410501_17_dialog_content = "That sure is far...",
  ui_story_5041_50410501_18_dialog_content = "Of course it is! You just make sure she gets this very important package!",
  ui_story_5041_50410501_19_dialog_content = "Sigh... He's still so overprotective.",
  ui_story_5041_50410501_20_dialog_content = "I just wanted to experience going out on my own...",
  ui_story_5041_50410501_21_dialog_content = "Well, I think it's a blessing in disguise to have someone in the family watching out for you all the time.",
  ui_story_5041_50410501_22_dialog_content = "Yeah!",
  ui_story_5041_50410501_23_dialog_content = "Let me see what my brother sent me.",
  ui_story_5041_50410501_24_dialog_content = "A notebook, and... what is this curved rod supposed to be for?",
  ui_story_5041_50410501_25_dialog_content = "As far as I know, it's a crowbar.",
  ui_story_5041_50410501_26_dialog_content = "You can lift heavy stuff with it, and use it for self-defense in a pinch.",
  ui_story_5041_50410501_27_dialog_content = "Don't tell me Sinsa wants you to use it as a defensive weapon...",
  ui_story_5041_50410501_28_dialog_content = "That sounds just like him...",
  ui_story_5041_50410501_29_dialog_content = "I'll read what's in the notebook.",
  ui_story_5041_50410501_30_dialog_content = "\"To Eve: Never hang out with these people\"?",
  ui_story_5041_50410501_31_dialog_content = "It's a long list of names!",
  ui_story_5041_50410501_32_dialog_content = "Why does it sound like a blacklist?",
  ui_story_5041_50410501_33_dialog_content = "Who's on it?",
  ui_story_5041_50410501_34_dialog_content = "Let me see... The Lumopolis judge with shark fangs.",
  ui_story_5041_50410501_35_dialog_content = "An Illumina researcher dubbed the \"Middle-Aged Man.\"",
  ui_story_5041_50410501_36_dialog_content = "An Umbraton merchant who's always smiling.",
  ui_story_5041_50410501_37_dialog_content = "And The Last Caelestite who runs around with the Colossus?",
  ui_story_5041_50410501_38_option_content = "Hey, that's me!",
  ui_story_5041_50410501_39_dialog_content = "Why is Sinsa calling me a bad guy...?",
  ui_story_5041_50410501_40_dialog_content = "This is what he wrote...",
  ui_story_5041_50410501_41_dialog_content = "\"PlayerName isn't a bad person, but there's one thing you gotta look out for...\"",
  ui_story_5041_50410501_42_dialog_content = "\"The propensity for convincing others to run around the world with him!\"",
  ui_story_5041_50410501_43_dialog_content = "Well, that's a fact.",
  ui_story_5041_50410501_44_dialog_content = "\"If you're not careful, you'll forget what you were meant to be doing and soon find yourself solving a crisis somewhere.\"",
  ui_story_5041_50410501_45_dialog_content = "\"So watch out!\"",
  ui_story_5041_50410501_46_dialog_content = "He didn't call you a bad guy, PlayerName!",
  ui_story_5041_50410501_47_dialog_content = "I'm happy about that, but...",
  ui_story_5041_50410501_48_dialog_content = "That still doesn't sit quite well with me somehow...",
  ui_story_5041_50410601_1_dialog_content = "Express package for you to sign for, Miss Azure!",
  ui_story_5041_50410601_2_dialog_content = "PlayerName? Are you the courier this time?",
  ui_story_5041_50410601_3_dialog_content = "You're often surrounded by such interesting people.",
  ui_story_5041_50410601_4_dialog_content = "A-All right, no teasing, please!",
  ui_story_5041_50410601_5_dialog_content = "This is from Zeta.",
  ui_story_5041_50410601_6_dialog_content = "That child looked pretty imposing as she was dropping off the package.",
  ui_story_5041_50410601_7_dialog_content = "She said—",
  ui_story_5041_50410601_8_dialog_content = "Ole couriers who rode the white dragon, the lone warrior of the dunes hereby entrusts you with a mission!",
  ui_story_5041_50410601_9_dialog_content = "Please deliver this to the blue demon lord inhabiting the Fire Realm.",
  ui_story_5041_50410601_10_dialog_content = "As a message of determination from a warrior!",
  ui_story_5041_50410601_11_dialog_content = "I'm guessing you're the blue demon lord she spoke of.",
  ui_story_5041_50410601_12_dialog_content = "A demon lord again? That seems to be my permanent role in her head.",
  ui_story_5041_50410601_13_dialog_content = "Well, this time was bound to come.",
  ui_story_5041_50410601_14_dialog_content = "\"This time\"? Why don't you seem at all surprised?",
  ui_story_5041_50410601_15_dialog_content = "Let's start from the beginning.",
  ui_story_5041_50410601_16_dialog_content = "Ever since that car race, Zeta's gotten into challenging me.",
  ui_story_5041_50410601_17_dialog_content = "She challlenges me on different things almost every ten days or so.",
  ui_story_5041_50410601_18_dialog_content = "Things like rock-paper-scissors, races, action games, and so on.",
  ui_story_5041_50410601_19_dialog_content = "But she's never won.",
  ui_story_5041_50410601_20_dialog_content = "That sounds like a lot...",
  ui_story_5041_50410601_21_dialog_content = "Playing around with an interesting girl like her is amusing for me too.",
  ui_story_5041_50410601_22_dialog_content = "Anyway, please sign for the package!",
  ui_story_5041_50410601_23_dialog_content = "Sure. I wonder what she's challenging me to this time.",
  ui_story_5041_50410601_24_dialog_content = "<color=#e8d9bb>*Rip*</color>",
  ui_story_5041_50410601_25_dialog_content = "A duck?",
  ui_story_5041_50410601_26_dialog_content = "This is new. But where's the challenge?",
  ui_story_5041_50410601_27_dialog_content = "I think I remember something.",
  ui_story_5041_50410601_28_dialog_content = "The duck's a recorder. Roy used one to record Regina's song before.",
  ui_story_5041_50410601_29_dialog_content = "Let me see. You press here, I think.",
  ui_story_5041_50410601_30_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5041_50410601_31_dialog_content = "Ole blue demon lord of the Fire Realm, the lone warrior of the dunes, challenges you!",
  ui_story_5041_50410601_32_dialog_content = "I shall demonstrate my unyielding resolve for world peace and the freedom of all Aurorians.",
  ui_story_5041_50410601_33_dialog_content = "The topic of this challenge shall be: Heavy metal rock!",
  ui_story_5041_50410601_34_dialog_content = "Regina, fellow warrior of the dunes, will be the judge and render fair decisions.",
  ui_story_5041_50410601_35_dialog_content = "If you lose, demon lord, you shall suffer severe punishment...",
  ui_story_5041_50410601_36_dialog_content = "The bar won't serve you drinks for a whole month!",
  ui_story_5041_50410601_37_dialog_content = "However, if the warrior loses...",
  ui_story_5041_50410601_38_dialog_content = "I shall punish my pathetic self by not consuming lollipops for 30 days!",
  ui_story_5041_50410601_39_dialog_content = "The time of the challenge is set for five days after this letter is sent. Be ready for me, demon lord!",
  ui_story_5041_50410601_40_dialog_content = "My, looks like we've got a real challenge this time...",
  ui_story_5041_50410601_41_dialog_content = "You're not good at metal rock, Azure?",
  ui_story_5041_50410601_42_dialog_content = "Oh no, I was talking about the punishment.",
  ui_story_5041_50410601_43_dialog_content = "One whole month without booze?",
  ui_story_5041_50410601_44_dialog_content = "I've got to show that kid just how good I am!"
}
return config
